const version = $('Obtener versión').first().json;
const rol = ($('Webhook Export').first().json.query?.rol || 'SOLICITANTE').toUpperCase();
const incluirInternos = rol === 'ADMIN';
const filas = $input.all().map((i, idx) => {
  const f = i.json;
  const base = {
    solicitud: version.id_solicitud,
    ciclo: version.ciclo,
    unidad: version.unidad,
    version: version.numero_version,
    n: idx + 1,
  };
  if (incluirInternos) base.aula = f.aula_codigo || 'Pendiente';
  Object.assign(base, {
    clave_curso: f.clave_curso,
    nombre_curso: f.nombre_curso || '',
    secuencia: f.secuencia || '',
    horario: f.horario || '',
    vacantes: f.vacantes,
    docentes: f.docentes || '',
    dia: f.dia || '',
    hora_inicio: f.hora_inicio || '',
    hora_fin: f.hora_fin || '',
    formato_curso: f.formato_curso || '',
    tipo_aula_solicitado: f.tipo_aula_solicitado || '',
    facultad_programa: f.facultad_programa || '',
    observaciones: f.observaciones_facultad || ''
  });
  if (incluirInternos) base.observaciones_intendencia = f.observaciones_intendencia || '';
  return base;
});
return [{json:{ok:true, version, rol, filas}}];
